ameCompleted\": false, \"unlockedRooms\": [\"secret-chamber\"], \"artifactUnlocked\": false, \"computerUnlocked\": true, \"periodicTableUnlocked\": true, \"microscopeEnigmeResolved\": true}','2025-06-20 08:39:35','2025-06-20 08:48:05'),(71,10,'2025-06-20 08:48:05',2040,214,1,'{\"score\": 2040, \"inventory\": [{\"id\": \"laboratory-key\", \"name\": \"Clé du laboratoire\", \"type\": \"key\", \"description\": \"Une clé ancienne qui ouvre la porte du laboratoire.\"}, {\"id\": \"professors-journal\", \"name\": \"Journal du Professeur\", \"type\": \"note\", \"description\": \"Un vieux journal contenant des notes énigmatiques\"}], \"currentRoom\": \"laboratory\", \"elapsedTime\": 185, \"gameCompleted\": false, \"unlockedRooms\": [\"library\", \"laboratory\"], \"artifactUnlocked\": false, \"computerUnlocked\": false, \"periodicTableUnlocked\": false, \"microscopeEnigmeResolved\": false}','2025-06-20 08:48:05','2025-06-20 08:51:46'),(72,10,'2025-06-20 08:51:46',1770,254,1,'{\"score\": 1770, \"inventory\": [{\"id\": \"professors-journal\", \"name\": \"Journal du Professeur\", \"type\": \"note\", \"description\": \"Un vieux journal contenant des notes énigmatiques\"}, {\"id\": \"laboratory-key\", \"name\": \"Clé du laboratoire\", \"type\": \"key\", \"description\": \"Une clé ancienne qui ouvre la porte du laboratoire.\"}, {\"id\": \"riddle-elements\", \"name\": \"Énigme des Éléments\", \"type\": \"riddle\", \"content\": {\"hint\": \"Pense aux éléments chimiques : Oxygène, Hydrogène, et un métal précieux...\", \"answer\": \"OHN\", \"riddle\": \"Mon premier : Je suis dans l\'air sans y être. Je suis vital mais invisible. Mon symbole est un souffle, et sans moi, plus de feu.\\n\\nMon second : Je suis liquide et pourtant j\'éteins le feu. Je tombe du ciel mais je peux inonder ton labo. On me voit mais je n\'ai pas de couleur.\\n\\nPour finir : Je suis solide, je brille, je conduis l\'électricité. Je suis souvent utilisé pour créer des alliages. Mon symbole commence par la 14e lett