INSERT INTO `inventory` VALUES (257,28,'mysterious-book','note','Livre Mystérieux','Un livre ancien aux pages jaunies contenant des secrets mystérieux',NULL,'2025-06-27 08:43:06'),(258,28,'laboratory-key','key','Clé du laboratoire','Une clé ancienne qui ouvre la porte du laboratoire.',NULL,'2025-06-27 08:43:41'),(259,28,'riddle-elements','riddle','Énigme des Éléments','Une énigme mystérieuse apparue sur le tableau périodique...','{\"hint\": \"Pense aux éléments chimiques : Oxygène, Hydrogène, et un métal précieux...\", \"answer\": \"OHN\", \"riddle\": \"Mon premier : Je suis dans l\'air sans y être. Je suis vital mais invisible. Mon symbole est un souffle, et sans moi, plus de feu.\\n\\nMon second : Je suis liquide et pourtant j\'éteins le feu. Je tombe du ciel mais je peux inonder ton labo. On me voit mais je n\'ai pas de couleur.\\n\\nPour finir : Je suis solide, je brille, je conduis l\'électricité. Je suis souvent utilisé pour créer des alliages. Mon symbole commence par la 14e lettre de l\'alphabet.\"}','2025-06-27 08:44:05'),(260,28,'crystal-key','key','Clé en Cristal','Une clé magnifique taillée dans un cristal translucide. Elle semble ouvrir quelque chose d\'important.',NULL,'2025-06-27 08:44:17'),(261,28,'riddle-apples','riddle','CXXX','Une énigme mystérieuse gravée sur un symbole solaire...','{\"hint\": \"Fais le calcul\", \"answer\": \"6\", \"riddle\": \"Un marchand dans un village médiéval, portant un panier de six pommes dorées cueillies à l\'aube.\\nEn chemin vers le marché, ton ami forgeron te demande un partage. Tu lui donnes la moitié des pommes.\\nUne herboriste t\'offre ensuite quatre pommes pour une herbe rare, que tu ajoutes au panier.\\nMais un corbeau voleur dérobe une pomme avant que tu n\'atteignes l\'étal.\\nCombien de pommes reste-t-il dans ton panier ?\"}','2025-06-27 08:44:23'),(262,28,'riddle-letter','riddle','XXCX','Une énigme mystérieuse apparue sur le symbole mystique...','{\"hint\": \"L\'ancêtre du SMS\", \"answer\": \"5\", \"riddle\": \"Je transmets les pensées d\'un homme à un autre,\\nJe traverse le monde et pourtant je ne bouge pas.\\nQui suis-je ?\\nObserve ma dernière lettre, trouve sa position dans l\'alphabet,\\net tu auras le chiffre du code.\"}','2025-06-27 08:44:25'),(263,28,'riddle-school','riddle','XXXC','Une énigme cachée dans un livre ancien...','{\"hint\": \"Nous y sommes actuellement\", \"answer\": \"3\", \"riddle\": \"Mon domaine n\'est ni maison ni château,\\nPourtant, chaque jour, on y entre sans fardeau.\\n\\nOn y cherche des clés, mais pas de métal,\\nPlutôt celles qui ouvrent un savoir vital.\\n\\nSilencieux parfois, agité souvent,\\nJ\'abrite l\'esprit des petits et des grands.\\nQui suis-je ?\\n\\nCompte mes voyelles et tu trouveras le chiffre pour le code\"}','2025-06-27 08:44:28'),(264,28,'riddle-mirror','riddle','XCXX','Une énigme gravée dans les hiéroglyphes...','{\"hint\": \"Je montre votre reflet...\", \"answer\": \"3\", \"riddle\": \"Je montre tout mais ne garde rien,\\nJe reflète le mal comme le bien.\\nDans mon monde, tout est inversé,\\nLa droite devient la gauche, c\'est prouvé.\\nQui suis-je, moi qui révèle la vérité,\\nMais dans un monde de réalité ?\\nTrouve ma position dans l\'alphabet, et tu sauras le chiffre\"}','2025-06-27 08:44:30'),(275,29,'laboratory-key','key','Clé du laboratoire','Une clé ancienne qui ouvre la porte du laboratoire.',NULL,'2025-06-27 09:45:56');
