INSERT INTO `riddles` VALUES ('professors-journal','library','Journal du Professeur','Le journal personnel du professeur disparu','{\"hint\": \"L\'année où l\'homme a fait un petit pas mais l\'humanité un grand pas.\", \"answer\": \"1969\", \"riddle\": \"20 Juillet 1969\\n\\nJe suis l\'année du changement,\\nL\'année où l\'homme quitta son monde rond.\\nÀ bord d\'un aigle, il se posa,\\nSur un sol que nul ne foulait.\\n\\nCe fut un petit pas pour l\'homme mais un grand pas pour l\'humanité.\\n\\nLa réponse est dans ce tiroir que plus personne n\'ouvre.\"}',100,'{\"x\": 0, \"y\": 1, \"z\": 0}',1,'2025-06-27 09:01:48','2025-06-27 09:01:48'),('riddle-apples','secret-chamber','CXXX','Une énigme mystérieuse gravée sur un symbole solaire','{\"hint\": \"Fais le calcul\", \"answer\": \"6\", \"riddle\": \"Un marchand dans un village médiéval, portant un panier de six pommes dorées cueillies à l\'aube.\\nEn chemin vers le marché, ton ami forgeron te demande un partage. Tu lui donnes la moitié des pommes.\\nUne herboriste t\'offre ensuite quatre pommes pour une herbe rare, que tu ajoutes au panier.\\nMais un corbeau voleur dérobe une pomme avant que tu n\'atteignes l\'étal.\\nCombien de pommes reste-t-il dans ton panier ?\"}',75,'{\"x\": 5, \"y\": 2.5, \"z\": -8}',1,'2025-06-27 09:01:48','2025-06-27 09:01:48'),('riddle-elements','laboratory','Énigme des Éléments','Une énigme mystérieuse apparue sur le tableau périodique','{\"hint\": \"Pense aux éléments chimiques : Oxygène, Hydrogène, et un métal précieux...\", \"answer\": \"OHN\", \"riddle\": \"Mon premier : Je suis dans l\'air sans y être. Je suis vital mais invisible. Mon symbole est un souffle, et sans moi, plus de feu.\\n\\nMon second : Je suis liquide et pourtant j\'éteins le feu. Je tombe du ciel mais je peux inonder ton labo. On me voit mais je n\'ai pas de couleur.\\n\\nPour finir : Je suis solide, je brille, je conduis l\'électricité. Je suis souvent utilisé pour créer des alliages. Mon symbole commence par la 14e lettre de l\'alphabet.\"}',120,'{\"x\": 1, \"y\": 1.5, \"z\": -5}',1,'2025-06-27 09:01:48','2025-06-27 09:01:48'),('riddle-letter','secret-chamber','XXCX','Une énigme mystérieuse apparue sur le symbole mystique','{\"hint\": \"L\'ancêtre du SMS\", \"answer\": \"5\", \"riddle\": \"Je transmets les pensées d\'un homme à un autre,\\nJe traverse le monde et pourtant je ne bouge pas.\\nQui suis-je ?\\nObserve ma dernière lettre, trouve sa position dans l\'alphabet,\\net tu auras le chiffre du code.\"}',75,'{\"x\": 2, \"y\": 1.8, \"z\": -5}',1,'2025-06-27 09:01:48','2025-06-27 09:01:48'),('riddle-mathematics','library','Énigme Mathématique','Une énigme mathématique trouvée dans le tiroir','{\"hint\": \"Pense aux nombres premiers et à leur ordre. Le premier nombre est impair et unique.\", \"answer\": \"7245\", \"riddle\": \"Quatre marchaient vers la vérité, mais un seul menait le pas...\\n\\nLe troisième suit le deuxième, deux fois plus fort.\\n\\nLe premier ne partage rien : il est impair, plus grand que le dernier, et unique en son genre.\\n\\nEnsemble, ils valent 18.\\n\\nAucun d\'eux ne se ressemble.\\n\\nEt le deuxième est plus petit que le quatrième.\"}',150,'{\"x\": 0, \"y\": 0, \"z\": 0}',1,'2025-06-27 09:01:48','2025-06-27 09:01:48'),('riddle-mirror','secret-chamber','XCXX','Une énigme gravée dans les hiéroglyphes','{\"hint\": \"Je montre votre reflet...\", \"answer\": \"3\", \"riddle\": \"Je montre tout mais ne garde rien,\\nJe reflète le mal comme le bien.\\nDans mon monde, tout est inversé,\\nLa droite devient la gauche, c\'est prouvé.\\nQui suis-je, moi qui révèle la vérité,\\nMais dans un monde de réalité ?\\nTrouve la position de ma première lettre dans l\'alphabet, et tu sauras le chiffre\"}',75,'{\"x\": -4, \"y\": 2, \"z\": 3}',1,'2025-06-27 09:01:48','2025-06-27 09:01:48'),('riddle-school','secret-chamber','XXXC','Une énigme cachée dans un livre ancien','{\"hint\": \"Nous y sommes actuellement\", \"answer\": \"3\", \"riddle\": \"Mon domaine n\'est ni maison ni château,\\nPourtant, chaque jour, on y entre sans fardeau.\\n\\nOn y cherche des clés, mais pas de métal,\\nPlutôt celles qui ouvrent un savoir vital.\\n\\nSilencieux parfois, agité souvent,\\nJ\'abrite l\'esprit des petits et des grands.\\nQui suis-je ?\\n\\nCompte mes voyelles et tu trouveras le chiffre pour le code\"}',75,'{\"x\": -3, \"y\": 1.5, \"z\": -2}',1,'2025-06-27 09:01:48','2025-06-27 09:01:48');
